// Same limp moments and muscle tone as tools/rigging/ragdoll.py (seconds into the death clip; tone start, fade seconds)
struct FDukeLimp { const TCHAR* Clip; float Limp, Tone, Fade; };
static const FDukeLimp GLimp[] = {
	{ TEXT("die"), 1.92f, 0.12f, 0.35f }, { TEXT("die_back"), 0.10f, 0.6f, 0.7f }, { TEXT("die_headshot"), 0.06f, 0.85f, 1.2f },
	{ TEXT("die_headshot_back"), 0.06f, 0.85f, 1.2f }, { TEXT("die_run"), 0.10f, 0.5f, 0.6f }, { TEXT("death_explosion"), 0.05f, 0.35f, 1.0f }, { TEXT("wounded_down"), 0.0f, 0.f, 0.1f } };
static const FDukeLimp* FindLimp(FName Clip)
{
	for (const FDukeLimp& L : GLimp) if (Clip == FName(L.Clip)) return &L;
	return nullptr;
}

static float CutTime(FName Clip)
{
	const FString C = Clip.ToString();
	if (C.StartsWith(TEXT("saber_death_"))) return 2.f / 30.f;
	if (C == TEXT("death_explosion_arm") || C == TEXT("death_explosion_leg") || C == TEXT("death_explosion_armleg")) return 1.f / 30.f;
	return -1.f;   // no dismemberment
}

ADukeTrooper::ADukeTrooper()
{
	PrimaryActorTick.bCanEverTick = true;
	AutoPossessAI = EAutoPossessAI::PlacedInWorldOrSpawned;
	AIControllerClass = AAIController::StaticClass();
	GetCapsuleComponent()->InitCapsuleSize(36.f, 92.f);
	bUseControllerRotationYaw = false;
	UCharacterMovementComponent* Move = GetCharacterMovement();
	Move->bOrientRotationToMovement = false;
	Move->MaxWalkSpeed = PatrolSpeed;
	Move->MaxWalkSpeedCrouched = 100.f;
	Move->NavAgentProps.bCanCrouch = true;
	Move->BrakingDecelerationWalking = 900.f;

	// The mesh faces +Y after FBX import; rotate it to face the actor's +X. Feet on the capsule bottom.
	GetMesh()->SetRelativeLocationAndRotation(FVector(0.f, 0.f, -92.f), FRotator(0.f, -90.f, 0.f));
	GetMesh()->SetAnimInstanceClass(UDukeTrooperAnimInstance::StaticClass());
	GetMesh()->VisibilityBasedAnimTickOption = EVisibilityBasedAnimTickOption::OnlyTickPoseWhenRendered;

	PhysAnim = CreateDefaultSubobject<UPhysicalAnimationComponent>(TEXT("PhysAnim"));
	PropMesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("PropMesh"));
	PropMesh->SetupAttachment(GetMesh(), TEXT("prop"));
	PropMesh->SetCollisionEnabled(ECollisionEnabled::NoCollision);
	PropMesh->SetVisibility(false);
	static ConstructorHelpers::FObjectFinder<UStaticMesh> PropCube(TEXT("/Engine/BasicShapes/Cube.Cube"));
	if (PropCube.Succeeded()) PropMesh->SetStaticMesh(PropCube.Object);
	MuzzleFlash = CreateDefaultSubobject<UPointLightComponent>(TEXT("MuzzleFlash"));
	MuzzleFlash->SetupAttachment(GetMesh(), TEXT("muzzle"));
	MuzzleFlash->SetIntensity(0.f);
	MuzzleFlash->SetAttenuationRadius(400.f);
	MuzzleFlash->SetLightColor(FLinearColor(1.f, 0.12f, 0.08f));
	MuzzleFlash->SetCastShadows(false);
}

void ADukeTrooper::LoadAssets()
{
	if (!GetMesh()->GetSkeletalMeshAsset())
		if (USkeletalMesh* SK = LoadObject<USkeletalMesh>(nullptr, *FString::Printf(TEXT("%s/SK_Trooper.SK_Trooper"), AssetRoot)))
		{
			GetMesh()->SetSkeletalMesh(SK);
			// the trooper is authored at 1.83 m; correct any unit mismatch from the FBX import
			const float H = SK->GetBounds().BoxExtent.Z * 2.f;
			if (H > 1.f && FMath::Abs(H - 183.f) > 15.f) GetMesh()->SetRelativeScale3D(FVector(183.f / H));
		}
	GetMesh()->SetAnimInstanceClass(UDukeTrooperAnimInstance::StaticClass());
	if (UDukeTrooperAnimInstance* A = Anim())
		for (const FName& N : ClipNames())
		{
			const FString Path = FString::Printf(TEXT("%s/Anims/A_Trooper_%s.A_Trooper_%s"), AssetRoot, *N.ToString(), *N.ToString());
			if (UAnimSequence* Seq = LoadObject<UAnimSequence>(nullptr, *Path)) A->Clips.Add(N, Seq);
			else UE_LOG(LogTemp, Warning, TEXT("DukeTrooper: missing clip %s"), *Path);
		}
	for (const FName& N : ClipNames())
		if (CutTime(N) > 0.f)
			if (USkeletalMesh* CM = LoadObject<USkeletalMesh>(nullptr, *FString::Printf(TEXT("%s/Cuts/SK_Trooper_Cut_%s.SK_Trooper_Cut_%s"), AssetRoot, *N.ToString(), *N.ToString())))
				CutMeshes.Add(N, CM);
	for (int32 i = 1; i <= 3; ++i)
		if (USoundBase* S = LoadObject<USoundBase>(nullptr, *FString::Printf(TEXT("/Game/DukeForge/Audio/S_Blaster_Fire_0%d.S_Blaster_Fire_0%d"), i, i)))
			FireSounds.Add(S);
}

void ADukeTrooper::RefreshAnimClips()
{
	if (UDukeTrooperAnimInstance* A = Anim())
		if (A->Clips.Num() == 0)
			for (const FName& N : ClipNames())
			{
				const FString Path = FString::Printf(TEXT("%s/Anims/A_Trooper_%s.A_Trooper_%s"), AssetRoot, *N.ToString(), *N.ToString());
				if (UAnimSequence* Seq = LoadObject<UAnimSequence>(nullptr, *Path)) A->Clips.Add(N, Seq);
			}
}

UDukeTrooperAnimInstance* ADukeTrooper::Anim() const
{
	return Cast<UDukeTrooperAnimInstance>(GetMesh()->GetAnimInstance());
}

void ADukeTrooper::BeginPlay()
{
	Super::BeginPlay();
	LoadAssets();
	Health = MaxHealth;
	Ammo = MagazineSize;
	Home = GetActorLocation();
	WaitUntil = GetWorld()->GetTimeSeconds() + FMath::FRandRange(0.5f, 2.f);
}

bool ADukeTrooper::CanSee(AActor* A) const
{
	if (!A) return false;
	const FVector Eye = GetActorLocation() + FVector(0, 0, 70.f);
	const FVector To = A->GetActorLocation() - Eye;
	if (To.Size() > SightRange) return false;
	const float Cos = FVector::DotProduct(GetActorForwardVector(), To.GetSafeNormal2D());
	if (State != EDukeTrooperState::Combat && Cos < FMath::Cos(FMath::DegreesToRadians(SightHalfAngle))) return false;
	FCollisionQueryParams P(SCENE_QUERY_STAT(DukeTrooperLOS), false, this);
	FHitResult H;
	return !GetWorld()->LineTraceSingleByChannel(H, Eye, A->GetActorLocation(), ECC_Visibility, P) || H.GetActor() == A;
}

void ADukeTrooper::Tick(float Dt)
{
	Super::Tick(Dt);
	const float Now = GetWorld()->GetTimeSeconds();
	if (FlashOff > 0.f && Now > FlashOff) { MuzzleFlash->SetIntensity(0.f); FlashOff = 0.f; }
	UDukeTrooperAnimInstance* A = Anim();
	if (State != EDukeTrooperState::Dead)
	{
		APawn* Player = UGameplayStatics::GetPlayerPawn(this, 0);
		if (State == EDukeTrooperState::Patrol && Player && CanSee(Player)) EnterCombat(Player, Now, true);
		if (bWounded && Now - WoundedAt > BleedOutSeconds) Die(TEXT("wounded_down"));   // bled out
		if (Squad.IsValid() && Order.Type != EDukeOrder::None) { if (State == EDukeTrooperState::Patrol || State == EDukeTrooperState::Combat) TickOrder(Dt, Now); }
		else if (State == EDukeTrooperState::Patrol) TickPatrol(Dt, Now);
		else if (State == EDukeTrooperState::Alert) { if (Now > ActionLock) { State = EDukeTrooperState::Combat; StateSince = Now; } }
		else if (State == EDukeTrooperState::Combat && !(Squad.IsValid() && Order.Type != EDukeOrder::None)) TickCombat(Dt, Now);
	}
	TickMoves(Dt, Now);
	if (State == EDukeTrooperState::Dead && bLiveRagdoll && !bRagdoll)
		if (const FDukeLimp* L = FindLimp(DeathClipName)) if (Now - DeathAt >= L->Limp) StartRagdoll(Now);
	if (bRagdoll) TickRagdoll(Now);
	if (State == EDukeTrooperState::Dead && !bCutApplied)
	{
		const float CT = CutTime(DeathClipName);
		if (CT > 0.f && Now - DeathAt >= CT)
			if (TObjectPtr<USkeletalMesh>* CM = CutMeshes.Find(DeathClipName))
			{
				// same skeleton: the death clip continues on the pre-cut mesh (remaining body + severed pieces)
				GetMesh()->SetSkeletalMesh(*CM, false);
				RefreshAnimClips();
				A = Anim();
				bCutApplied = true;
			}
	}
	if (A)
	{
		A->State.DeathClip = DeathClipName;
		A->State.DeathTime = State == EDukeTrooperState::Dead ? Now - DeathAt : 0.f;
		A->State.bKneeling = State == EDukeTrooperState::Combat && Now < KneelUntil && RollStart < 0.f;
		A->State.bClimbing = bClimbing;
		A->State.bLimping = bLimping; A->State.bSneak = bSneak && State == EDukeTrooperState::Patrol;
		A->State.bWounded = bWounded && !bBeingDragged;
		A->State.bDragged = bBeingDragged;
		A->State.bDragging = DragPartner.IsValid() && !bWounded;
		A->State.bProne = bProne && !bWounded;
		if (bTreating && !bWounded) A->State.DutyClip = TEXT("medic_treat");
		const bool bDutyOrder = Order.Type == EDukeOrder::Duty || Order.Type == EDukeOrder::Attention || Order.Type == EDukeOrder::Stack;
		A->State.DutyClip = (bDutyOrder && !bWounded && !DragPartner.IsValid()) ? Order.Clip : NAME_None;
		// props: a supply crate while hauling, a datapad while checking papers (Unreal cube scaled; swap in real meshes on a Blueprint)
		const FName DC = A->State.DutyClip;
		const bool bCrate = DC == TEXT("carry_crate"), bPad = DC == TEXT("check_credentials");
		PropMesh->SetVisibility(bCrate || bPad);
		PropMesh->SetRelativeScale3D(bCrate ? FVector(0.40f, 0.40f, 0.34f) : FVector(0.12f, 0.02f, 0.18f));
		if (Order.Type == EDukeOrder::Cover || Order.Type == EDukeOrder::Suppress || Order.Type == EDukeOrder::Breach) A->State.bAiming = true;
		if (Order.Type == EDukeOrder::Cover && CoverKind != NAME_None && !bWounded && Now >= CoverFireUntil) A->State.DutyClip = CoverKind;   // cover_low_idle / cover_high_idle
		A->State.ClimbSpeed = bClimbing ? 50.f : 0.f;
		const FVector V = GetActorTransform().InverseTransformVectorNoScale(GetVelocity());
		A->State.LocalVelocity = FVector(V.X, V.Y, 0.f);
		A->State.bAiming = State == EDukeTrooperState::Combat;
		A->State.bCrouched = State == EDukeTrooperState::Combat && Now < CrouchUntil;
		A->State.bFalling = GetCharacterMovement()->IsFalling();
		A->State.bDead = State == EDukeTrooperState::Dead;
		if (Target.IsValid() && State == EDukeTrooperState::Combat)
		{
			const FVector To = Target->GetActorLocation() - (GetActorLocation() + FVector(0, 0, 60.f));
			A->State.AimPitch = FMath::FInterpTo(A->State.AimPitch, FMath::RadiansToDegrees(FMath::Atan2(To.Z, To.Size2D())), Dt, 6.f);
		}
		else A->State.AimPitch = FMath::FInterpTo(A->State.AimPitch, 0.f, Dt, 4.f);
	}
}

void ADukeTrooper::TickPatrol(float Dt, float Now)
{
	UCharacterMovementComponent* Move = GetCharacterMovement();
	Move->MaxWalkSpeed = bSneak ? 70.f : PatrolSpeed;   // tiptoe_walk is authored at 70 cm/s
	if (Now < WaitUntil) return;
	if (UDukeTrooperAnimInstance* A = Anim()) A->State.IdleVariant = NAME_None;
	const FVector Goal = PatrolPoints.Num() ? Home + PatrolPoints[PatrolIndex % PatrolPoints.Num()] : Home;
	const FVector To = (Goal - GetActorLocation()) * FVector(1, 1, 0);
	if (To.Size() < 60.f)
	{
		// reached a waypoint: pause, scan, sometimes signal, then continue
		PatrolIndex = PatrolPoints.Num() ? (PatrolIndex + 1) % PatrolPoints.Num() : 0;
		WaitUntil = Now + FMath::FRandRange(PauseSeconds.X, PauseSeconds.Y);
		if (UDukeTrooperAnimInstance* A = Anim())
		{
			// waypoint pause: scan the area, stretch the neck, peek over cover on tiptoe, or wave the next man on
			const float R = FMath::FRand();
			if (R < 0.35f) A->State.IdleVariant = TEXT("patrol_look");
			else if (R < 0.50f) A->State.IdleVariant = TEXT("look_around");
			else if (R < 0.62f) A->PlayAction(TEXT("neck_roll"));
			else if (R < 0.74f) A->PlayAction(TEXT("tiptoe_peek"));
			else if (R < 0.87f) A->PlayAction(TEXT("beckon"));
			else A->PlayAction(TEXT("signal_moveup"));
		}
		return;
	}
	SetActorRotation(FMath::RInterpTo(GetActorRotation(), To.Rotation(), Dt, 4.f));
	UpdateLook(Dt);
	// walk once roughly facing the goal, so feet and facing agree
	if (FVector::DotProduct(GetActorForwardVector(), To.GetSafeNormal()) > 0.7f) AddMovementInput(To.GetSafeNormal(), 1.f);
}

void ADukeTrooper::EnterCombat(AActor* Who, float Now, bool bSignal)
{
	Target = Who;
	LastSeen = Who ? Who->GetActorLocation() : GetActorLocation();
	LastSeenTime = Now;
	if (UDukeTrooperAnimInstance* A = Anim())
	{
		A->State.IdleVariant = NAME_None;
		if (bSignal) { A->PlayAction(TEXT("signal_halt"), 1.6f); ActionLock = Now + A->ClipLength(TEXT("signal_halt")) / 1.6f * 0.7f; }
	}
	State = bSignal ? EDukeTrooperState::Alert : EDukeTrooperState::Combat;
	if (Squad.IsValid() && Who) Squad->ReportThreat(this, Who);
	StateSince = Now;
	NextShot = Now + (bSignal ? 1.1f : 0.35f);
	BurstLeft = BurstSize;
}

void ADukeTrooper::TickCombat(float Dt, float Now)
{
	AActor* T = Target.Get();
	if (!T || (Cast<APawn>(T) == nullptr)) { State = EDukeTrooperState::Patrol; return; }
	const bool bSee = CanSee(T);
	if (bSee) { LastSeen = T->GetActorLocation(); LastSeenTime = Now; }
	if (Now - LastSeenTime > 8.f) { State = EDukeTrooperState::Patrol; Target = nullptr; return; } // lost them

	// face the target
	const FVector To = (LastSeen - GetActorLocation()) * FVector(1, 1, 0);
	const float Dist = To.Size();
	SetActorRotation(FMath::RInterpTo(GetActorRotation(), To.Rotation(), Dt, 7.f));

	// movement: hold the preferred range, strafe between bursts (aim-walk clips are direction-blended)
	UCharacterMovementComponent* Move = GetCharacterMovement();
	Move->MaxWalkSpeed = CombatMoveSpeed;
	const bool bCrouched = Now < CrouchUntil || Now < KneelUntil || RollStart >= 0.f;
	if (!bCrouched && Now > ReloadUntil)
	{
		if (Now > MoveUntil)
		{
			MoveUntil = Now + FMath::FRandRange(1.0f, 2.5f);
			if (Dist > PreferredRange.Y || !bSee) MoveInput = FVector2D(1.f, FMath::FRandRange(-0.4f, 0.4f));
			else if (Dist < PreferredRange.X) MoveInput = FVector2D(-1.f, 0.f);
			else MoveInput = FMath::FRand() < 0.35f ? FVector2D::ZeroVector : FVector2D(0.f, FMath::RandBool() ? 1.f : -1.f);
		}
		const FVector Fwd = GetActorForwardVector(), Right = GetActorRightVector();
		const FVector Dir = Fwd * MoveInput.X + Right * MoveInput.Y;
		if (!Dir.IsNearlyZero()) AddMovementInput(Dir.GetSafeNormal(), 1.f);
	}

	// reload when the power cell is empty
	if (Ammo <= 0 && Now > ReloadUntil)
	{
		if (UDukeTrooperAnimInstance* A = Anim()) { A->PlayAction(TEXT("reload")); ReloadUntil = Now + FMath::Max(1.f, A->ClipLength(TEXT("reload"))); }
		Ammo = MagazineSize;
		return;
	}
	if (Now < ReloadUntil || Now < ActionLock) return;

	// fire in bursts while the target is visible
	if (bSee && Now >= NextShot)
	{
		FireBolt(Now);
		--Ammo;
		if (--BurstLeft > 0) NextShot = Now + ShotInterval;
		else
		{
			BurstLeft = BurstSize; NextShot = Now + FMath::FRandRange(BurstPause.X, BurstPause.Y);
			if (Now > KneelUntil && RollStart < 0.f && FMath::FRand() < RollChance) StartRoll(Now);
		}
	}
}

void ADukeTrooper::FireBolt(float Now)
{
	AActor* T = Target.Get();
	if (!T) return;
	const FVector Muzzle = GetMesh()->DoesSocketExist(TEXT("muzzle")) ? GetMesh()->GetSocketLocation(TEXT("muzzle")) : GetActorLocation() + GetActorForwardVector() * 60.f + FVector(0, 0, 50.f);
	const FVector Aim = (T->GetActorLocation() + FVector(0, 0, 25.f)) - Muzzle;
	const FVector Dir = FMath::VRandCone(Aim.GetSafeNormal(), FMath::DegreesToRadians(SpreadDegrees));
	ADukeBlasterBolt::Fire(GetWorld(), this, Muzzle + Dir * 10.f, Dir, BoltDamage, BoltSpeed, BoltColor);
	MuzzleFlash->SetIntensity(9000.f);
	FlashOff = Now + 0.05f;
	if (FireSounds.Num())
		UGameplayStatics::PlaySoundAtLocation(this, FireSounds[FMath::RandRange(0, FireSounds.Num() - 1)], Muzzle, 0.8f, FMath::FRandRange(0.94f, 1.06f));
	if (UDukeTrooperAnimInstance* A = Anim()) A->PlayAction(TEXT("shoot"), 0.3f / FMath::Max(ShotInterval, 0.12f));
}

float ADukeTrooper::TakeDamage(float DamageAmount, FDamageEvent const& DamageEvent, AController* EventInstigator, AActor* DamageCauser)
{
	const float Dmg = Super::TakeDamage(DamageAmount, DamageEvent, EventInstigator, DamageCauser);
	if (State == EDukeTrooperState::Dead || Dmg <= 0.f) return Dmg;
	const float Now = GetWorld()->GetTimeSeconds();
	AActor* From = EventInstigator && EventInstigator->GetPawn() ? EventInstigator->GetPawn() : DamageCauser;
	const UClass* DT = DamageEvent.DamageTypeClass ? DamageEvent.DamageTypeClass.Get() : nullptr;
	if (DT && DT->IsChildOf(UDukeSaberDamageType::StaticClass()))
	{
		// lightsaber: two burns, the third blade contact dismembers
		if (++SaberHits >= 3) { Die(PickSaberEnding(DamageEvent)); return Dmg; }
		if (UDukeTrooperAnimInstance* A = Anim()) { A->PlayAction(SaberHits == 1 ? TEXT("saber_hit_1") : TEXT("saber_hit_2")); ActionLock = Now + 0.7f; }
		if (State != EDukeTrooperState::Combat && From) EnterCombat(From, Now, false);
		return Dmg;
	}
	Health -= Dmg;
	if (DT && DT->IsChildOf(UDukeExplosionDamageType::StaticClass()) && Health <= 0.f) { Die(PickExplosionEnding(DamageEvent, From)); return Dmg; }
	if (Health > 0.f && DamageEvent.IsOfType(FPointDamageEvent::ClassID))
	{
		const FHitResult& H = static_cast<const FPointDamageEvent&>(DamageEvent).HitInfo;
		const float FeetZ = GetActorLocation().Z - GetCapsuleComponent()->GetScaledCapsuleHalfHeight();
		const FString B = H.BoneName.ToString();
		if (B.StartsWith(TEXT("foot")) || B.StartsWith(TEXT("ball")) || (!H.ImpactPoint.IsNearlyZero() && H.ImpactPoint.Z < FeetZ + 22.f))
		{
			if (UDukeTrooperAnimInstance* A = Anim()) A->PlayAction(TEXT("hit_foot"));
			bLimping = true; ActionLock = Now + 0.8f;
			PatrolSpeed = FMath::Min(PatrolSpeed, 90.f); CombatMoveSpeed = FMath::Min(CombatMoveSpeed, 90.f);
			if (State != EDukeTrooperState::Combat && From) EnterCombat(From, Now, false);
			return Dmg;
		}
	}
	if (Health <= 0.f) { Die(PickDeath(DamageEvent, From, Dmg)); return Dmg; }
	if (!bWounded && Squad.IsValid() && Health < MaxHealth * 0.35f && FMath::FRand() < WoundChance) { BecomeWounded(Now); if (From) Squad->ReportThreat(this, From); return Dmg; }
	if (UDukeTrooperAnimInstance* A = Anim())
	{
		// directional reaction: front / back / left / right of the shooter; a nearby blast makes him duck instead
		FName R = TEXT("hit_front");
		if (DT && DT->IsChildOf(UDukeExplosionDamageType::StaticClass())) R = TEXT("flinch_duck");
		else if (From)
		{
			const FVector To = (From->GetActorLocation() - GetActorLocation()).GetSafeNormal2D();
			const float F = FVector::DotProduct(GetActorForwardVector(), To), Rt = FVector::DotProduct(GetActorRightVector(), To);
			R = FMath::Abs(Rt) > FMath::Abs(F) ? (Rt > 0.f ? FName(TEXT("hit_right")) : FName(TEXT("hit_left"))) : (F > 0.f ? FName(TEXT("hit_front")) : FName(TEXT("hit_back")));
		}
		A->PlayAction(R);
		ActionLock = Now + 0.35f;
	}
	if (State != EDukeTrooperState::Combat && From) EnterCombat(From, Now, false);
	// take a knee under fire once hurt
	if (Health < MaxHealth * 0.6f && Now > CrouchUntil + 3.f && FMath::FRand() < 0.5f) CrouchUntil = Now + FMath::FRandRange(2.f, 4.f);
	return Dmg;
}

// Choose the death that fits the shot: momentum (running), headshot, blown back, or the default chest-hit crumple.
FName ADukeTrooper::PickDeath(const FDamageEvent& DamageEvent, AActor* From, float Damage) const
{
	if (GetVelocity().Size2D() > 300.f) return TEXT("die_run");
	FVector HitAt = FVector::ZeroVector;
	FName Bone = NAME_None;
	if (DamageEvent.IsOfType(FPointDamageEvent::ClassID))
	{
		const FPointDamageEvent& PE = static_cast<const FPointDamageEvent&>(DamageEvent);
		HitAt = PE.HitInfo.ImpactPoint; Bone = PE.HitInfo.BoneName;
	}
	const bool bHead = Bone == TEXT("head") || Bone == TEXT("neck_01") ||
		(!HitAt.IsNearlyZero() && HitAt.Z > GetActorLocation().Z + GetCapsuleComponent()->GetScaledCapsuleHalfHeight() * 0.62f);
	if (bHead)
	{
		// limp while standing, then falls away from the shot: backward if hit from the front, forward if from behind
		const bool bFromFront = !From || FVector::DotProduct(GetActorForwardVector(), (From->GetActorLocation() - GetActorLocation()).GetSafeNormal2D()) > 0.f;
		return bFromFront ? FName(TEXT("die_headshot_back")) : FName(TEXT("die_headshot"));
	}
	const bool bFromBehind = From && FVector::DotProduct(GetActorForwardVector(), (From->GetActorLocation() - GetActorLocation()).GetSafeNormal2D()) < -0.2f;
	if (bFromBehind || Damage >= MaxHealth * 0.5f || FMath::FRand() < 0.3f) return TEXT("die_back");
	return TEXT("die");
}

void ADukeTrooper::Die(FName DeathClip)
{
	if (UDukeTrooperAnimInstance* A = Anim()) A->State.DeathClip = DeathClip;
	DeathClipName = DeathClip; DeathAt = GetWorld()->GetTimeSeconds(); bCutApplied = false;
	if (DragPartner.IsValid()) { if (bBeingDragged) DragPartner->EndDrag(); else EndDrag(); }
	if (Squad.IsValid()) Squad->ReportDown(this);
	bClimbing = false; RollStart = -1.f; MantleStart = -1.f;
	State = EDukeTrooperState::Dead;
	GetCharacterMovement()->DisableMovement();
	GetCapsuleComponent()->SetCollisionEnabled(ECollisionEnabled::NoCollision);
	MuzzleFlash->SetIntensity(0.f);
	SetLifeSpan(30.f);
}

// ---------------- lightsaber and explosion endings ----------------
FName ADukeTrooper::PickSaberEnding(const FDamageEvent& DamageEvent) const
{
	FVector HitAt = FVector::ZeroVector;
	if (DamageEvent.IsOfType(FPointDamageEvent::ClassID)) HitAt = static_cast<const FPointDamageEvent&>(DamageEvent).HitInfo.ImpactPoint;
	if (HitAt.IsNearlyZero())
	{
		static const FName Any[5] = { TEXT("saber_death_arm"), TEXT("saber_death_leg"), TEXT("saber_death_head"), TEXT("saber_death_half"), TEXT("saber_death_diagonal") };
		return Any[FMath::RandRange(0, 4)];
	}
	// height above the feet and side of the body decide where the blade landed
	const FVector L = GetActorTransform().InverseTransformPosition(HitAt);
	const float Z = L.Z + GetCapsuleComponent()->GetScaledCapsuleHalfHeight();   // cm above the feet
	if (Z > 150.f) return TEXT("saber_death_head");
	if (Z < 85.f) return TEXT("saber_death_leg");
	if (L.Y > 18.f && Z > 115.f) return TEXT("saber_death_arm");             // right side, upper arm height
	return FMath::RandBool() ? FName(TEXT("saber_death_half")) : FName(TEXT("saber_death_diagonal"));
}

FName ADukeTrooper::PickExplosionEnding(const FDamageEvent& DamageEvent, AActor* From) const
{
	FVector Origin = From ? From->GetActorLocation() : GetActorLocation() + GetActorForwardVector() * 100.f;
	if (DamageEvent.IsOfType(FRadialDamageEvent::ClassID)) Origin = static_cast<const FRadialDamageEvent&>(DamageEvent).Origin;
	const FVector L = GetActorTransform().InverseTransformPosition(Origin);
	if (L.Size2D() < 80.f) return TEXT("death_explosion_leg");                 // right underneath: launched, loses a leg
	if (L.X < -40.f) return TEXT("death_explosion_armleg");                   // behind: cartwheels forward
	if (L.Y < -60.f && FMath::FRand() < 0.7f) return TEXT("death_explosion_arm");   // his left: thrown right, loses the left arm
	return FMath::FRand() < 0.25f ? FName(TEXT("death_explosion_arm")) : FName(TEXT("death_explosion"));
}

// ---------------- roll, kneel, mantle, ladder ----------------
// travel curves match the authored root motion of roll_to_kneel (2.3 m) and mantle (0.82 m forward, 1.1 m up)
static float RollTravel(float T)
{
	const float V0 = 320.f, T1 = 0.35f, T2 = 1.15f;
	if (T < T1) return V0 * T;
	if (T < T2) { const float U = (T - T1) / (T2 - T1); return V0 * T1 + V0 * (T2 - T1) * (U - U * U * 0.5f); }
	return V0 * T1 + V0 * (T2 - T1) * 0.5f;
}

void ADukeTrooper::StartRoll(float Now)
{
	if (UDukeTrooperAnimInstance* A = Anim()) A->PlayAction(TEXT("roll_to_kneel"));
	RollStart = Now; RollFrom = GetActorLocation(); RollDir = GetActorForwardVector();
	KneelUntil = Now + 1.2f + KneelSeconds;
	NextShot = Now + 1.5f;
}

void ADukeTrooper::Mantle(float LedgeHeight)
{
	if (IsDead()) return;
	if (UDukeTrooperAnimInstance* A = Anim()) A->PlayAction(TEXT("mantle"));
	MantleStart = GetWorld()->GetTimeSeconds(); MantleFrom = GetActorLocation(); MantleHeight = LedgeHeight;
	GetCharacterMovement()->SetMovementMode(MOVE_Flying);
}

void ADukeTrooper::StartLadderClimb(float Height)
{
	if (IsDead()) return;
	bClimbing = true; ClimbTop = GetActorLocation().Z + Height;
	GetCharacterMovement()->SetMovementMode(MOVE_Flying);
	GetCharacterMovement()->StopMovementImmediately();
}

void ADukeTrooper::TickMoves(float Dt, float Now)
{
	if (RollStart >= 0.f)
	{
		const float T = Now - RollStart;
		const FVector Want = RollFrom + RollDir * RollTravel(FMath::Min(T, 1.2f));
		SetActorLocation(FVector(Want.X, Want.Y, GetActorLocation().Z), true);
		if (T > 1.2f) RollStart = -1.f;
	}
	if (MantleStart >= 0.f)
	{
		const float T = Now - MantleStart;
		auto Ease = [](float X) { X = FMath::Clamp(X, 0.f, 1.f); return X * X * (3.f - 2.f * X); };
		const float Up = Ease((T - 0.22f) / 0.73f) * (MantleHeight + 5.f);
		const float Fwd = Ease((T - 0.2f) / 1.4f) * 82.f;
		SetActorLocation(MantleFrom + GetActorForwardVector() * Fwd + FVector(0, 0, Up), false);
		if (T > 1.7f) { MantleStart = -1.f; GetCharacterMovement()->SetMovementMode(MOVE_Walking); }
	}
	if (bClimbing)
	{
		AddActorWorldOffset(FVector(0, 0, 50.f * Dt), true);
		if (GetActorLocation().Z >= ClimbTop) { bClimbing = false; Mantle(40.f); }
	}
}

// ---------------- live ragdoll with fading muscle tone ----------------
void ADukeTrooper::StartRagdoll(float Now)
{
	const FDukeLimp* L = FindLimp(DeathClipName);
	ToneStart = L ? L->Tone : 0.3f; ToneFade = L ? L->Fade : 0.6f;
	bRagdoll = true; RagdollAt = Now; bGrounded = false;
	USkeletalMeshComponent* M = GetMesh();
	M->SetCollisionProfileName(TEXT("Ragdoll"));
	M->SetCollisionEnabled(ECollisionEnabled::QueryAndPhysics);
	PhysAnim->SetSkeletalMeshComponent(M);
	FPhysicalAnimationData D; D.bIsLocalSimulation = false;
	D.OrientationStrength = 1500.f * ToneStart; D.AngularVelocityStrength = 100.f * ToneStart; D.PositionStrength = 0.f; D.VelocityStrength = 0.f;
	PhysAnim->ApplyPhysicalAnimationSettingsBelow(TEXT("pelvis"), D, true);
	M->SetAllBodiesBelowSimulatePhysics(TEXT("pelvis"), true, true);   // momentum carries over from the animation
	M->SetAllBodiesBelowPhysicsBlendWeight(TEXT("pelvis"), 1.f);
}

void ADukeTrooper::TickRagdoll(float Now)
{
	USkeletalMeshComponent* M = GetMesh();
	// ground contact: the pelvis or chest within 30 cm of whatever is under it (floor, crate, stair)
	if (!bGrounded)
		for (const TCHAR* B : { TEXT("pelvis"), TEXT("spine_03"), TEXT("head") })
		{
			const FVector P = M->GetBoneLocation(B);
			FHitResult H; FCollisionQueryParams Q(SCENE_QUERY_STAT(DukeRagdollGround), false, this);
			if (GetWorld()->LineTraceSingleByChannel(H, P, P - FVector(0, 0, 30.f), ECC_Visibility, Q)) { bGrounded = true; break; }
		}
	const float T = Now - RagdollAt;
	float K = ToneStart * FMath::Pow(FMath::Max(0.f, 1.f - T / ToneFade), 1.5f);
	if (bGrounded) K = 0.f;   // completely limp once it lies on something
	FPhysicalAnimationData D; D.bIsLocalSimulation = false;
	D.OrientationStrength = 1500.f * K; D.AngularVelocityStrength = 100.f * K;
	PhysAnim->ApplyPhysicalAnimationSettingsBelow(TEXT("pelvis"), D, true);
}

// ---------------- squad orders ----------------
void ADukeTrooper::PlayGesture(FName Clip) { if (UDukeTrooperAnimInstance* A = Anim()) A->PlayAction(Clip); }

void ADukeTrooper::MoveToward(const FVector& Where, float Speed, bool bBackward)
{
	const FVector To = (Where - GetActorLocation()) * FVector(1, 1, 0);
	if (To.Size() < 40.f) return;
	GetCharacterMovement()->MaxWalkSpeed = Speed;
	if (!bBackward) SetActorRotation(FMath::RInterpTo(GetActorRotation(), To.Rotation(), GetWorld()->GetDeltaSeconds(), 6.f));
	AddMovementInput(To.GetSafeNormal(), 1.f);
}

void ADukeTrooper::BecomeWounded(float Now)
{
	bWounded = true; WoundedAt = Now;
	GetCharacterMovement()->MaxWalkSpeed = 30.f;
	if (DragPartner.IsValid()) EndDrag();
	if (Squad.IsValid()) Squad->ReportWounded(this);
}

void ADukeTrooper::Revive()
{
	if (!bWounded || IsDead()) return;
	bWounded = false; Health = MaxHealth * 0.5f;
	GetCharacterMovement()->MaxWalkSpeed = PatrolSpeed;
	PlayGesture(TEXT("getup_back")); BusyUntil = GetWorld()->GetTimeSeconds() + 2.4f;   // gets up before doing anything else
}

void ADukeTrooper::BeginDrag(ADukeTrooper* W)
{
	if (!W || W->bBeingDragged) return;
	DragPartner = W; W->DragPartner = this; W->bBeingDragged = true;
	W->GetCapsuleComponent()->SetCollisionEnabled(ECollisionEnabled::NoCollision);
	W->GetCharacterMovement()->DisableMovement();
	W->AttachToActor(this, FAttachmentTransformRules::KeepWorldTransform);
	W->SetActorRelativeLocation(FVector(DragForward, -DragLeft, 0.f));   // Unreal +Y is the character's right
	W->SetActorRelativeRotation(FRotator::ZeroRotator);      // same heading: lying on his back, head toward the rescuer
}

void ADukeTrooper::EndDrag()
{
	ADukeTrooper* W = DragPartner.Get();
	DragPartner = nullptr;
	if (!W) return;
	W->DragPartner = nullptr; W->bBeingDragged = false;
	W->DetachFromActor(FDetachmentTransformRules::KeepWorldTransform);
	W->GetCapsuleComponent()->SetCollisionEnabled(ECollisionEnabled::QueryAndPhysics);
	W->GetCharacterMovement()->SetMovementMode(MOVE_Walking);
	W->SetActorRotation(FRotator(0.f, W->GetActorRotation().Yaw, 0.f));
}

void ADukeTrooper::TickOrder(float Dt, float Now)
{
	AActor* Tgt = Order.Target.Get();
	if (bBeingDragged) return;                                   // carried by the rescuer
	if (bWounded) { MoveToward(Order.Location, 30.f); return; }  // crawls toward cover
	const float Speed2D = GetVelocity().Size2D();
	if (LastSpeed > 300.f && Speed2D < 60.f && Now > BusyUntil) { PlayGesture(TEXT("run_stop")); }   // brakes out of a run
	LastSpeed = Speed2D;
	if (TurnStart >= 0.f)
	{
		const float K = FMath::Clamp((Now - TurnStart) / 0.8f, 0.f, 1.f);
		SetActorRotation(FRotator(0.f, TurnFrom + FMath::FindDeltaAngleDegrees(TurnFrom, TurnTo) * (K * K * (3.f - 2.f * K)), 0.f));
		if (K >= 1.f) TurnStart = -1.f;
	}
	if (VaultStart >= 0.f)
	{
		const float K = FMath::Clamp((Now - VaultStart) / 1.3f, 0.f, 1.f);
		SetActorLocation(VaultFrom + GetActorForwardVector() * 160.f * (K * K * (3.f - 2.f * K)) + FVector(0, 0, 55.f * FMath::Sin(PI * FMath::Min(1.f, K / 0.75f))), false);
		if (K >= 1.f) { VaultStart = -1.f; GetCharacterMovement()->SetMovementMode(MOVE_Walking); }
		return;
	}
	if (Now < BusyUntil) return;
	bTreating = false;
	if (Order.Type != EDukeOrder::Suppress && bProne) { bProne = false; PlayGesture(TEXT("getup_front")); BusyUntil = Now + 2.4f; return; }
	// a ~1 m wall in the way while moving: vault it
	if (Speed2D > 120.f)
	{
		FCollisionQueryParams VQ(SCENE_QUERY_STAT(DukeVault), false, this); FHitResult HLow, HHigh;
		const FVector P0 = GetActorLocation() - FVector(0, 0, GetCapsuleComponent()->GetScaledCapsuleHalfHeight() - 50.f);
		const FVector Fw = GetActorForwardVector() * 90.f;
		if (GetWorld()->LineTraceSingleByChannel(HLow, P0, P0 + Fw, ECC_Visibility, VQ) && !GetWorld()->LineTraceSingleByChannel(HHigh, P0 + FVector(0, 0, 80.f), P0 + FVector(0, 0, 80.f) + Fw * 1.6f, ECC_Visibility, VQ))
		{ StartVault(); return; }
	}
	const float Dist = FVector::Dist2D(GetActorLocation(), Order.Location);
	auto Face = [&](const FVector& P) { SetActorRotation(FMath::RInterpTo(GetActorRotation(), ((P - GetActorLocation()) * FVector(1, 1, 0)).Rotation(), Dt, 7.f)); };
	auto ShootIfSeen = [&](bool bBlind)
	{
		if (!Tgt || Now < NextShot || Now < ReloadUntil) return;
		if (Ammo <= 0) { PlayGesture(TEXT("reload")); ReloadUntil = Now + 2.2f; Ammo = MagazineSize; return; }
		if (bBlind || CanSee(Tgt)) { Target = Tgt; FireBolt(Now); --Ammo; NextShot = Now + (bBlind ? 0.14f : ShotInterval) * (--BurstLeft > 0 ? 1.f : 4.f); if (BurstLeft <= 0) BurstLeft = BurstSize; }
	};
	switch (Order.Type)
	{
	case EDukeOrder::Move:
		MoveToward(Order.Location, Dist > 800.f ? 420.f : PatrolSpeed);   // jog when far, walk otherwise
		break;
	case EDukeOrder::Cover:
		if (Dist > 60.f) { CoverKind = NAME_None; MoveToward(Order.Location, Dist > 500.f ? 420.f : CombatMoveSpeed, false); if (Tgt && Dist < 500.f) Face(Tgt->GetActorLocation()); }
		else
		{
			if (Tgt) FaceTarget(Tgt->GetActorLocation(), Dt, Now);
			if (CoverKind == NAME_None && Tgt) CoverKind = CoverHeightAt(GetActorLocation(), Tgt->GetActorLocation());
			if (CoverKind == NAME_None) { CrouchUntil = Now + 0.5f; ShootIfSeen(false); break; }       // no real cover here: crouch and fight
			// pop up (low wall) or lean out (tall wall) to fire, then back into cover
			if (Now > NextCoverFire && Tgt)
			{
				const bool bLow = CoverKind == TEXT("cover_low_idle");
				PlayGesture(bLow ? TEXT("cover_low_fire") : TEXT("cover_lean_fire_r"));
				CoverFireUntil = Now + (bLow ? 2.0f : 1.9f); NextCoverFire = CoverFireUntil + FMath::FRandRange(1.0f, 2.5f);
				BurstLeft = 3; NextShot = Now + (bLow ? 0.5f : 0.45f);
			}
			if (Now < CoverFireUntil && Now >= NextShot && BurstLeft > 0 && Tgt) { Target = Tgt; FireBolt(Now); --Ammo; --BurstLeft; NextShot = Now + 0.25f; }
		}
		break;
	case EDukeOrder::Suppress:
		if (Duty == EDukeDuty::Heavy && Dist <= 60.f && !bProne) { bProne = true; PlayGesture(TEXT("go_prone")); BusyUntil = Now + 1.6f; break; }   // the heavy goes prone to suppress
		if (Dist > 60.f) MoveToward(Order.Location, CombatMoveSpeed);
		if (Tgt) { Face(Tgt->GetActorLocation()); ShootIfSeen(true); }  // keeps their heads down even without a clear shot
		break;
	case EDukeOrder::Rescue:
	{
		ADukeTrooper* W = Cast<ADukeTrooper>(Tgt);
		if (!W || W->IsDead() || !W->IsWounded()) { EndDrag(); Order.Type = EDukeOrder::None; break; }
		if (DragPartner.Get() == W)
		{
			// walk backward to cover, dragging him, blaster pointed back toward the enemy
			const FVector Away = (Order.Location - GetActorLocation()).GetSafeNormal2D();
			SetActorRotation(FMath::RInterpTo(GetActorRotation(), (-Away).Rotation(), Dt, 5.f));
			GetCharacterMovement()->MaxWalkSpeed = 90.f; AddMovementInput(Away, 1.f);
			if (Dist < 80.f) { EndDrag(); if (Duty == EDukeDuty::Medic) W->Revive(); }
		}
		else
		{
			const float ToW = FVector::Dist2D(GetActorLocation(), W->GetActorLocation());
			const bool bAtCover = FVector::Dist2D(W->GetActorLocation(), Order.Location) < 150.f;
			if (ToW > 110.f) MoveToward(W->GetActorLocation() + (GetActorLocation() - W->GetActorLocation()).GetSafeNormal2D() * 100.f, 420.f);
			else if (!bAtCover) BeginDrag(W);
			else if (Duty == EDukeDuty::Medic) { bTreating = true; FaceTarget(W->GetActorLocation(), Dt, Now); if (Now - W->WoundedAt > 6.f) W->Revive(); }   // kneels and treats him there
			else CrouchUntil = Now + 0.5f;                                                                                  // guards him
		}
		break;
	}
	case EDukeOrder::Duty: case EDukeOrder::Attention: case EDukeOrder::Stack:
		if (Dist > 50.f) MoveToward(Order.Location, Order.Clip == TEXT("carry_crate") ? 100.f : (Order.Type == EDukeOrder::Stack ? CombatMoveSpeed : PatrolSpeed));
		else if (Tgt) Face(Tgt->GetActorLocation());
		break;
	case EDukeOrder::Breach:
		if (Dist > 60.f) { MoveToward(Order.Location, 200.f); }
		else if (Tgt) Face(Tgt->GetActorLocation());
		break;
	default: break;
	}
}

// ---------------- turning, cover height, vault ----------------
void ADukeTrooper::FaceTarget(const FVector& P, float Dt, float Now)
{
	const float Want = ((P - GetActorLocation()) * FVector(1, 1, 0)).Rotation().Yaw;
	const float Delta = FMath::FindDeltaAngleDegrees(GetActorRotation().Yaw, Want);
	if (TurnStart >= 0.f) return;
	if (FMath::Abs(Delta) > 70.f && GetVelocity().Size2D() < 20.f && Now >= BusyUntil)
	{
		// stepping turn: 90 deg with the feet moving, instead of spinning on the spot
		PlayGesture(Delta > 0.f ? TEXT("turn_r90") : TEXT("turn_l90"));   // Unreal yaw + = right turn
		TurnFrom = GetActorRotation().Yaw; TurnTo = TurnFrom + FMath::Sign(Delta) * 90.f; TurnStart = Now;
		return;
	}
	SetActorRotation(FMath::RInterpTo(GetActorRotation(), FRotator(0.f, Want, 0.f), Dt, 7.f));
}

// Low cover blocks a crouching trooper (60 cm) but not a standing one (150 cm); tall cover blocks both.
FName ADukeTrooper::CoverHeightAt(const FVector& Spot, const FVector& Threat) const
{
	FCollisionQueryParams Q(SCENE_QUERY_STAT(DukeCoverHeight), false, this);
	const float FeetZ = Spot.Z - GetCapsuleComponent()->GetScaledCapsuleHalfHeight();
	auto Blocked = [&](float H)
	{
		FHitResult Hit; const FVector A(Spot.X, Spot.Y, FeetZ + H);
		const FVector Dir = ((Threat - Spot) * FVector(1, 1, 0)).GetSafeNormal();
		return GetWorld()->LineTraceSingleByChannel(Hit, A, A + Dir * 150.f, ECC_Visibility, Q);
	};
	if (!Blocked(60.f)) return NAME_None;
	return Blocked(150.f) ? FName(TEXT("cover_high_idle")) : FName(TEXT("cover_low_idle"));
}

void ADukeTrooper::StartVault()
{
	PlayGesture(TEXT("vault")); VaultStart = GetWorld()->GetTimeSeconds(); VaultFrom = GetActorLocation();
	BusyUntil = VaultStart + 1.3f;
	GetCharacterMovement()->SetMovementMode(MOVE_Flying);
}

// Head look-at while not aiming: turns neck and head toward the nearest pawn in front (within ~12 m), else ahead.
void ADukeTrooper::UpdateLook(float Dt)
{
	UDukeTrooperAnimInstance* A = Anim(); if (!A) return;
	float Yaw = 0.f, Pitch = 0.f, Best = LookRange;
	const FVector Eye = GetActorLocation() + FVector(0, 0, 70.f);
	for (TActorIterator<APawn> It(GetWorld()); It; ++It)
	{
		APawn* Other = *It; if (Other == this) continue;
		const FVector To = Other->GetActorLocation() + FVector(0, 0, 50.f) - Eye; const float D = To.Size();
		if (D > Best) continue;
		const FRotator Rel = (GetActorTransform().InverseTransformVectorNoScale(To)).Rotation();
		if (FMath::Abs(Rel.Yaw) > 100.f) continue;
		Best = D; Yaw = FMath::Clamp(Rel.Yaw, -80.f, 80.f); Pitch = FMath::Clamp(Rel.Pitch, -40.f, 40.f);
	}
	A->State.LookYaw = FMath::FInterpTo(A->State.LookYaw, Yaw, Dt, 3.f);
	A->State.LookPitch = FMath::FInterpTo(A->State.LookPitch, Pitch, Dt, 3.f);
}
